draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw book
  ctx.fillStyle = '#964B00';
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-75, 100, 150);
  ctx.fill();
  ctx.stroke();

  // draw stick figure reading book
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2-120, H/2-50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2-120, H/2-30);
  ctx.lineTo(W/2-120, H/2+20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-120, H/2-10);
  ctx.lineTo(W/2-90, H/2+10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-120, H/2-10);
  ctx.lineTo(W/2-150, H/2+10);
  ctx.stroke();

  // draw wisdom words
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply Wisdom', W/2, H/2+100 + 20 * Math.sin(t));

  ctx.restore();
}
